import requests
import time


def fetch(url):
    max_retries = 3
    for attempt in range(max_retries + 1):
        try:
            r = requests.get(url, timeout=5)
            r.raise_for_status()
            return r.json()
        except (requests.Timeout, requests.ConnectionError) as e:
            if attempt < max_retries:
                wait_time = 2 ** attempt  # 1s, 2s, 4s
                time.sleep(wait_time)
            else:
                raise
        except Exception:
            raise
